<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_admin();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
if (!$id || $id < 1) { flash('error', 'Invalid report selected.'); redirect('admin/reports.php'); }
$statement = db()->prepare('SELECT * FROM reports WHERE id = ? LIMIT 1'); $statement->execute([$id]); $report = $statement->fetch();
if (!$report) { flash('error', 'Report not found.'); redirect('admin/reports.php'); }
$historyStmt = db()->prepare('SELECT h.old_status, h.new_status, h.notes, h.changed_at, u.full_name AS changed_by_name FROM report_status_history h LEFT JOIN users u ON u.id = h.changed_by WHERE h.report_id = ? ORDER BY h.changed_at DESC, h.id DESC'); $historyStmt->execute([$id]); $history = $historyStmt->fetchAll();
$pageTitle = 'Review ' . $report['reference_no'];
require __DIR__ . '/../includes/header.php';
?>
<div class="dashboard-heading"><div><a class="back-link" href="<?= e(url('admin/reports.php')) ?>">← Back to reports</a><span class="eyebrow">REPORT REVIEW</span><h1><?= e($report['reference_no']) ?></h1><p>Review submitted information and document any status change.</p></div><span class="status-pill <?= e(status_class($report['status'])) ?> status-large"><?= e($report['status']) ?></span></div>
<div class="review-layout"><div class="review-main"><section class="panel detail-panel"><div class="panel-heading"><div><h2>Submitted details</h2><p>Submitted <?= e(format_date($report['created_at'])) ?></p></div><span class="panel-step">#<?= (int)$report['id'] ?></span></div><div class="details-grid"><div><small>Reporter name</small><strong><?= e($report['reporter_name']) ?></strong></div><div><small>Reporter email</small><strong><?= e($report['reporter_email']) ?></strong></div><div><small>Vehicle number</small><strong><?= e($report['vehicle_number']) ?></strong></div><div><small>Violation category</small><strong><?= e($report['violation_type']) ?></strong></div><div class="detail-wide"><small>Location</small><strong><?= e($report['location_text']) ?></strong></div><div><small>Incident date/time</small><strong><?= e(format_date($report['incident_at'])) ?></strong></div><div><small>Last updated</small><strong><?= e(format_date($report['updated_at'])) ?></strong></div></div><div class="detail-description"><small>Citizen description</small><p><?= nl2br(e($report['description'])) ?></p></div>
<?php if (!empty($report['evidence_path'])): ?><div class="evidence-box"><div><h3>Evidence photograph</h3><p class="muted-text">Visible to signed-in authority users.</p></div><img class="evidence-image" src="<?= e(url('evidence.php?id=' . (int)$report['id'])) ?>" alt="Evidence photograph submitted with this report" loading="lazy"></div><?php else: ?><div class="empty-evidence">No photograph was included with this report.</div><?php endif; ?></section>
<section class="panel history-panel"><div class="panel-heading"><div><h2>Status history</h2><p>Recorded workflow changes</p></div></div><?php if (!$history): ?><p class="muted-text">No status history has been recorded.</p><?php else: ?><div class="history-list"><?php foreach ($history as $event): ?><div class="history-item"><span class="history-dot"></span><div><div class="history-title"><strong><?= e($event['new_status']) ?></strong><small><?= e(format_date($event['changed_at'])) ?></small></div><p><?= e($event['notes'] ?: 'No additional notes.') ?></p><small>By <?= e($event['changed_by_name'] ?: 'System / citizen submission') ?></small></div></div><?php endforeach; ?></div><?php endif; ?></section></div>
<aside class="panel update-panel"><div class="panel-heading"><div><h2>Update review</h2><p>Changes are recorded in history.</p></div></div><form method="post" action="<?= e(url('admin/update_report.php')) ?>" class="stack-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="report_id" value="<?= (int)$report['id'] ?>"><div class="form-field"><label for="status">New status *</label><select id="status" name="status" required><?php foreach (['Submitted','Under Review','Verified','Rejected','Closed'] as $status): ?><option value="<?= e($status) ?>" <?= $report['status'] === $status ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="notes">Reviewer remarks *</label><textarea id="notes" name="notes" rows="5" maxlength="1500" minlength="3" required placeholder="Record what was reviewed, why the status changed, or what information is missing."><?= e($report['officer_notes']) ?></textarea><small>Remarks may be shown to the person tracking this report. Do not include confidential internal notes.</small></div><div class="form-field"><label for="penalty_amount">Illustrative penalty estimate (₹, optional)</label><input id="penalty_amount" name="penalty_amount" type="number" min="0" max="1000000" step="0.01" value="<?= e($report['penalty_amount']) ?>"><small>Academic display only</small></div><button type="submit" class="btn btn-primary btn-wide" data-confirm="Save this review update?">Save update</button></form><div class="dashboard-disclaimer"><strong>Review responsibly</strong><p>Evidence should be assessed fairly. A report status does not automatically establish liability.</p></div></aside></div>
